probes.shared:
let s = Rc::new(RefCell::new(vec![1i64, 2, 3]));
let v = vec![Rc::clone(&s), Rc::clone(&s)];
v[0].borrow_mut().push(99);
let r = if v[1].borrow().last() == Some(&99) && Rc::ptr_eq(&v[0], &v[1]) { "shared" } else { "copied" };

