probes.cycle:
struct N { name: String, selfref: RefCell<Option<Rc<N>>> }
let n = Rc::new(N { name: "loop".to_string(), selfref: RefCell::new(None) });
*n.selfref.borrow_mut() = Some(Rc::clone(&n));
let held = n.selfref.borrow();
let r = if Rc::ptr_eq(held.as_ref().unwrap(), &n) { "cycle" } else { "no-cycle" };
